import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Create plane geometry with atlas aspect ratio (512:320 = 1.6)
  const atlasAspectRatio = 512 / 320;
  const planeHeight = 0.6;
  const planeWidth = planeHeight * atlasAspectRatio;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load texture via cached loader
  const textureMap = ctx.textureLoader.load(
    config.imageUrl || '/prism-mock/home/nodes/floating-accent.png'
  );
  textureMap.colorSpace = THREE.SRGBColorSpace;

  // Create TSL-based material
  const material = new MeshBasicNodeMaterial({
    colorNode: texture(textureMap),
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Create and position mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(...(config.position || [-3.2, 1, 0.06]));
  mesh.rotation.order = 'YXZ';
  mesh.rotation.set(...(config.rotation || [0, 0, 0]));
  mesh.scale.set(...(config.scale || [1, 1, 1]));

  group.add(mesh);

  // Add text content via fontAtlas
  if (config.textContent && Array.isArray(config.textContent) && config.textContent.length > 0) {
    const textData = config.textContent[0];
    const textValue = textData.value || textData || 'Collection 1';

    const colorValue = config.colors?.ink
      ? parseInt(config.colors.ink.replace('#', ''), 16)
      : 0x16161d;

    const textMesh = ctx.fontAtlas.createText(textValue, {
      size: 0.34, // headline size
      weight: textData.weight || 400,
      color: colorValue,
      align: 'center',
      valign: 'middle',
    });

    if (textMesh) {
      textMesh.position.copy(mesh.position);
      textMesh.position.z += 0.01;
      group.add(textMesh);
    }
  }

  // Cleanup handler
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  group.userData.handlers = {};

  return group;
}
